window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-dec7167a39f3b93f"]={"versions": [{"id": "FIG-dec7167a39f3b93f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Schichten- und Pyramidenmodell zur Veranschaulichung der Dokumentationshierarchie und Änderungshistorie (History Information) in AUTOSAR. Das Diagramm setzt den Abstraktionsgrad bzw. Geltungsbereich (Scope / abstraction) in Beziehung zur Menge der Änderungseinträge (Number of entries) über drei Spezifikations- und Dokumentationsebenen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich horizontal in drei Ebenen und zwei gegenläufige Trichter-/Pyramidenformen:</p>\n<ul class=\"fig-list\"><li>Obere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Specification (all docs)“ (hohe Abstraktion / breiter Scope).\n</li><li>Mitte: Dokumentationsartefakt „Release Overview“.\n</li><li>Rechts: Inhaltsbeschreibung für „Release only“ („Changes by concepts (lists also affected documents)“) sowie „Release and revision“ unterteilt in:\n<ul class=\"fig-list\"><li>„Chapter „Summary of changes“: Maintenance work, changes in document structure“\n</li><li>„Chapter „Specification Overview“: list of released specifications“\n</li><li>„Chapter „Remarks to known technical deficiencies“: global technical deficiencies and deficiencies from documents“\n</li><li>„Chapter „Release History“: subset of external histories of documents“\n</li></ul>\n</li></ul>\n</li><li>Mittlere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Document“.\n</li><li>Mitte: Dokumentationsartefakt „Document external history“.\n</li><li>Rechts: Inhaltsbeschreibung für „Release only“ („Changes / impact on document by concepts“) sowie Vorgaben unter „Guidance for document owner“:\n<ul class=\"fig-list\"><li>„State major changes with high impact or“\n</li><li>„Put a standard entry: „minor corrections/clarifications/editorial changes““\n</li></ul>\n</li></ul>\n</li><li>Untere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Requirement“ (konkrete Einzelanforderungsebene / schmaler Scope).\n</li><li>Mitte: Dokumentationsartefakt „Change Documentation“ (größte Breite der aufrechten Pyramide / maximale Anzahl an Einträgen).\n</li><li>Rechts: Inhaltsbeschreibung „Changes on CR granularity“ (Change-Request-Granularität).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne Kontrollfluss oder zeitliche Ablaufsequenz. Die Darstellung visualisiert zwei gegenläufige Dimensionen:</p>\n<ul class=\"fig-list\"><li>Von oben nach unten nimmt der fachliche Abstraktionsgrad („Scope / abstraction“) von der Gesamtspezifikation über Einzeldokumente bis hinunter zu individuellen Requirements ab.\n</li><li>Umgekehrt steigt von oben nach unten die Anzahl der Änderungseinträge („Number of entries“) von hochaggregierten Release-Übersichten über dokumentspezifische Historien bis hin zu feingranularen Change-Request-Einträgen in der Change Documentation.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Leitfaden für Spezifikationsautoren und Dokumentverantwortliche (Document Owners) zur korrekten Pflege von Änderungshistorien und Release-Informationen:</p>\n<ul class=\"fig-list\"><li>Auf Dokumentenebene („Document external history“) sind bei Haupt-Releases („Release only“) konzeptbedingte Auswirkungen zu benennen; für untergeordnete Änderungen ist der Standardtext <code>minor corrections/clarifications/editorial changes</code> zu verwenden oder signifikante Änderungen mit hohem Einfluss sind explizit auszuweisen.\n</li><li>Die Release Overview fasst dokumentspezifische Historien zusammen und ergänzt globale technische Unzulänglichkeiten (Technical Deficiencies) sowie strukturelle Änderungen.\n</li><li>Technische Details und feingranulare Fehlerbehebungen verbleiben auf Change-Request-Ebene in der Change Documentation.\n</li></ul>"}, {"id": "FIG-27ac667fbb9be2e3", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Schichten- und Pyramidenmodell zur Veranschaulichung der Dokumentationshierarchie und Änderungshistorie (History Information) in AUTOSAR. Das Diagramm setzt den Abstraktionsgrad bzw. Geltungsbereich (Scope / abstraction) in Beziehung zur Menge der Änderungseinträge (Number of entries) über drei Spezifikations- und Dokumentationsebenen hinweg.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild gliedert sich horizontal in drei Ebenen und zwei gegenläufige Trichter-/Pyramidenformen:</p>\n<ul class=\"fig-list\"><li>Obere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Specification (all docs)“ (hohe Abstraktion / breiter Scope).\n</li><li>Mitte: Dokumentationsartefakt „Release Overview“.\n</li><li>Rechts: Inhaltsbeschreibung für „Release only“ („Changes by concepts (lists also affected documents)“) sowie „Release and revision“ unterteilt in:\n<ul class=\"fig-list\"><li>„Chapter „Summary of changes“: Maintenance work, changes in document structure“\n</li><li>„Chapter „Specification Overview“: list of released specifications“\n</li><li>„Chapter „Remarks to known technical deficiencies“: global technical deficiencies and deficiencies from documents“\n</li><li>„Chapter „Release History“: subset of external histories of documents“\n</li></ul>\n</li></ul>\n</li><li>Mittlere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Document“.\n</li><li>Mitte: Dokumentationsartefakt „Document external history“.\n</li><li>Rechts: Inhaltsbeschreibung für „Release only“ („Changes / impact on document by concepts“) sowie Vorgaben unter „Guidance for document owner“:\n<ul class=\"fig-list\"><li>„State major changes with high impact or“\n</li><li>„Put a standard entry: „minor corrections/clarifications/editorial changes““\n</li></ul>\n</li></ul>\n</li><li>Untere Ebene:\n<ul class=\"fig-list\"><li>Links: Geltungsbereich „Requirement“ (konkrete Einzelanforderungsebene / schmaler Scope).\n</li><li>Mitte: Dokumentationsartefakt „Change Documentation“ (größte Breite der aufrechten Pyramide / maximale Anzahl an Einträgen).\n</li><li>Rechts: Inhaltsbeschreibung „Changes on CR granularity“ (Change-Request-Granularität).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Zuordnungsdiagramm ohne Kontrollfluss oder zeitliche Ablaufsequenz. Die Darstellung visualisiert zwei gegenläufige Dimensionen:</p>\n<ul class=\"fig-list\"><li>Von oben nach unten nimmt der fachliche Abstraktionsgrad („Scope / abstraction“) von der Gesamtspezifikation über Einzeldokumente bis hinunter zu individuellen Requirements ab.\n</li><li>Umgekehrt steigt von oben nach unten die Anzahl der Änderungseinträge („Number of entries“) von hochaggregierten Release-Übersichten über dokumentspezifische Historien bis hin zu feingranularen Change-Request-Einträgen in der Change Documentation.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Leitfaden für Spezifikationsautoren und Dokumentverantwortliche (Document Owners) zur korrekten Pflege von Änderungshistorien und Release-Informationen:</p>\n<ul class=\"fig-list\"><li>Auf Dokumentenebene („Document external history“) sind bei Haupt-Releases („Release only“) konzeptbedingte Auswirkungen zu benennen; für untergeordnete Änderungen ist der Standardtext <code>minor corrections/clarifications/editorial changes</code> zu verwenden oder signifikante Änderungen mit hohem Einfluss sind explizit auszuweisen.\n</li><li>Die Release Overview fasst dokumentspezifische Historien zusammen und ergänzt globale technische Unzulänglichkeiten (Technical Deficiencies) sowie strukturelle Änderungen.\n</li><li>Technische Details und feingranulare Fehlerbehebungen verbleiben auf Change-Request-Ebene in der Change Documentation.\n</li></ul>"}], "trans": [{"from": "FIG-dec7167a39f3b93f", "to": "FIG-27ac667fbb9be2e3", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
